	public static void GenerateScript_ByteArrayAdd(string linePrefix, string fileName, byte[] bytes, StringBuilder sb)
	{
		sb.AppendLine(linePrefix + "#region " + fileName);
		sb.AppendLine(linePrefix + "_preloadBytesDic.Add");
		sb.AppendLine(linePrefix + "(");
		sb.AppendLine(linePrefix + "\t" + $"\"{fileName}\",");
		sb.AppendLine(linePrefix + "\tnew byte[]");
		sb.AppendLine(linePrefix + "\t{");
		sb.Append(linePrefix + "\t\t");
		for (int i = 0; i < bytes.Length; i++)
		{
			byte b = bytes[i];
			if (i % 30 == 0 && i > 0)
			{
				sb.AppendLine();
				sb.Append(linePrefix + "\t\t");
			}
			sb.Append($"0x{b:X2}, ");
		}
		sb.AppendLine();
		sb.AppendLine(linePrefix + "\t}");
		sb.AppendLine(linePrefix + ");");
		sb.AppendLine(linePrefix + "#endregion");
		sb.AppendLine();
	}

	public static byte[] GetBytes(string keyPath)
	{
		if (_preloadBytesDic.TryGetValue(keyPath, out var value))
		{
			return value;
		}
		StringBuilder stringBuilder = new StringBuilder();
		foreach (KeyValuePair<string, byte[]> item in _preloadBytesDic)
		{
			stringBuilder.AppendLine($"Preload {item.Key}: {item.Value.Length} bytes");
		}
		JitOption.JitLog(stringBuilder.ToString());
		return null;
	}
}
